}

::deep .area-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #2b2d42;
}

::deep .channel-description {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #6c757d;
}

/* ===== Message List ===== */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 24px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8d99ae;
    font-size: 0.85rem;
}

::deep .message-item {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    margin-bottom: 4px;
    transition: background-color 0.15s;
}

::deep .message-item:hover {
    background: #f8f9fa;
}

::deep .message-item.highlighted {
    background: #fff3cd;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #2b2d42;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #8d99ae;
}

::deep .message-content {
    font-size: 0.9rem;
    color: #343a40;
    line-height: 1.5;
    word-wrap: break-word;
}

/* ===== Reactions ===== */
::deep .reaction-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 0.8rem;
    transition: background-color 0.15s, border-color 0.15s;
