::deep .reaction-emoji {
    font-size: 0.9rem;
}

::deep .reaction-count {
    font-weight: 600;
    color: #495057;
}

/* ===== Thread Link ===== */
::deep .thread-link {
    display: inline-block;
    margin-top: 6px;
    padding: 2px 0;
    border: none;
    background: transparent;
    color: #0d6efd;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

::deep .thread-link:hover {
