}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #2b2d42;
}

::deep .btn-close-thread {
    border: none;
    background: transparent;
    font-size: 1.1rem;
    color: #6c757d;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.15s;
}

::deep .btn-close-thread:hover {
